import{_ as e,c as r,o as a,a0 as l}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"da/blog/elite-goal-setting.md","filePath":"da/blog/elite-goal-setting.md"}');const t=e({name:"da/blog/elite-goal-setting.md"},[["render",function(e,i,t,n,o,s){return a(),r("div",null,[...i[0]||(i[0]=[l('<h1 id="malsætning-for-eliteatleter" tabindex="-1">Målsætning for eliteatleter <a class="header-anchor" href="#malsætning-for-eliteatleter" aria-label="Permalink to &quot;Målsætning for eliteatleter&quot;">​</a></h1><p>Målsætning virker simpel: beslut dig for, hvad du vil, og arbejd hen imod det. Men målsætning på eliteniveau er mere nuanceret. De rigtige mål fremskynder udviklingen; de forkerte skaber frustration og stagnation.</p><h2 id="ud-over-grundlæggende-mal" tabindex="-1">Ud over grundlæggende mål <a class="header-anchor" href="#ud-over-grundlæggende-mal" aria-label="Permalink to &quot;Ud over grundlæggende mål&quot;">​</a></h2><p>De fleste spillere sætter sig resultatmål: &quot;Vind det regionale mesterskab.&quot; Disse mål har problemer:</p><ul><li>Du kan ikke fuldt ud kontrollere resultaterne</li><li>De skaber pres uden retning</li><li>Succes eller fiasko er binært</li><li>De vejleder ikke den daglige praksis</li></ul><p>Elitemålsætning går dybere.</p><h2 id="malhierarkiet" tabindex="-1">Målhierarkiet <a class="header-anchor" href="#malhierarkiet" aria-label="Permalink to &quot;Målhierarkiet&quot;">​</a></h2><h3 id="niveau-1-drømmemal-1-5-ar" tabindex="-1">Niveau 1: Drømmemål (1-5 år) <a class="header-anchor" href="#niveau-1-drømmemal-1-5-ar" aria-label="Permalink to &quot;Niveau 1: Drømmemål (1-5 år)&quot;">​</a></h3><p>Dine ultimative ambitioner:</p><ul><li>&quot;Konkurrer på nationalt niveau&quot;</li><li>&quot;Bliv anerkendt som en eliteskytte&quot;</li><li>&quot;Vind et stort mesterskab&quot;</li></ul><p>Disse giver retning og motivation, men er ikke handlingsrettede i det daglige.</p><h3 id="niveau-2-præstationsmal-sæson-ar" tabindex="-1">Niveau 2: Præstationsmål (sæson/år) <a class="header-anchor" href="#niveau-2-præstationsmal-sæson-ar" aria-label="Permalink to &quot;Niveau 2: Præstationsmål (sæson/år)&quot;">​</a></h3><p>Målbare forbedringer i dit spil:</p><ul><li>&quot;Øg skydepræcisionen fra 60% til 70%&quot;</li><li>&quot;Reducer uprovokerede fejl med 25%&quot;</li><li>&quot;Udvikl en pålidelig plombée&quot;</li></ul><p>Disse er inden for din kontrol og målbare.</p><h3 id="niveau-3-procesmal-dagligt-ugentligt" tabindex="-1">Niveau 3: Procesmål (dagligt/ugentligt) <a class="header-anchor" href="#niveau-3-procesmal-dagligt-ugentligt" aria-label="Permalink to &quot;Niveau 3: Procesmål (dagligt/ugentligt)&quot;">​</a></h3><p>Handlinger, der fremmer forbedringer:</p><ul><li>&quot;Komplet rutine før kast ved hvert kast&quot;</li><li>&quot;Øv visualisering i 10 minutter dagligt&quot;</li><li>&quot;Træn skydeteknik 3 gange om ugen&quot;</li></ul><p>Disse er fuldt kontrollerbare og bygger mod præstationsmål.</p><h2 id="smart-rammeværket" tabindex="-1">SMART+ rammeværket <a class="header-anchor" href="#smart-rammeværket" aria-label="Permalink to &quot;SMART+ rammeværket&quot;">​</a></h2><p>Gå ud over grundlæggende SMART-mål:</p><h3 id="bestemt" tabindex="-1">Bestemt <a class="header-anchor" href="#bestemt" aria-label="Permalink to &quot;Bestemt&quot;">​</a></h3><p>Ikke &quot;forbedre min pegeteknik&quot;, men &quot;udvikle en ensartet demiportée, der lander inden for 30 cm fra målet fra 8 meter.&quot;</p><h3 id="malbar" tabindex="-1">Målbar <a class="header-anchor" href="#malbar" aria-label="Permalink to &quot;Målbar&quot;">​</a></h3><p>Definer, hvordan du vil spore fremskridt:</p><ul><li>Succesprocenter</li><li>Konsistensmålinger</li><li>Videoanalysemarkører</li></ul><h3 id="opnaeligt-men-udfordrende" tabindex="-1">Opnåeligt, men udfordrende <a class="header-anchor" href="#opnaeligt-men-udfordrende" aria-label="Permalink to &quot;Opnåeligt, men udfordrende&quot;">​</a></h3><p>Målet bør kræve vækst, men være realistisk. En 60%-skytte, der sigter mod 65%, er opnåeligt; en sigtning mod 90% er fantasi.</p><h3 id="relevant" tabindex="-1">Relevant <a class="header-anchor" href="#relevant" aria-label="Permalink to &quot;Relevant&quot;">​</a></h3><p>Mål skal være forbundet med dine større ambitioner og adressere faktiske svagheder, ikke kun det, der er let at forbedre.</p><h3 id="tidsbegrænset" tabindex="-1">Tidsbegrænset <a class="header-anchor" href="#tidsbegrænset" aria-label="Permalink to &quot;Tidsbegrænset&quot;">​</a></h3><p>Sæt klare deadlines:</p><ul><li>&quot;Ved sæsonens afslutning&quot;</li><li>&quot;Inden for 3 måneder&quot;</li><li>&quot;Ved det nationale mesterskab&quot;</li></ul><h3 id="personligt-meningsfuld" tabindex="-1">+ Personligt meningsfuld <a class="header-anchor" href="#personligt-meningsfuld" aria-label="Permalink to &quot;+ Personligt meningsfuld&quot;">​</a></h3><p>Målet skal have betydning for DIG, ikke kun din træner eller dine holdkammerater. Indre motivation opretholder indsatsen, når fremskridtet er langsomt.</p><h2 id="proces-vs-resultatfokus" tabindex="-1">Proces vs. Resultatfokus <a class="header-anchor" href="#proces-vs-resultatfokus" aria-label="Permalink to &quot;Proces vs. Resultatfokus&quot;">​</a></h2><h3 id="problemet-med-resultatmal" tabindex="-1">Problemet med resultatmål <a class="header-anchor" href="#problemet-med-resultatmal" aria-label="Permalink to &quot;Problemet med resultatmål&quot;">​</a></h3><p>&quot;Vind kampen&quot; skaber problemer:</p><ul><li>Angst over ting, du ikke kan kontrollere</li><li>Distraktion fra udførelsen</li><li>Alt-eller-intet-tænkning</li><li>Pres uden vejledning</li></ul><h3 id="styrken-ved-procesmal" tabindex="-1">Styrken ved procesmål <a class="header-anchor" href="#styrken-ved-procesmal" aria-label="Permalink to &quot;Styrken ved procesmål&quot;">​</a></h3><p>&quot;Udfør min rutine før indtagelse perfekt&quot; tilbyder:</p><ul><li>Fuld kontrol</li><li>Klart fokus</li><li>Øjeblikkelig feedback</li><li>Bygger naturligt mod resultater</li></ul><h3 id="balancen" tabindex="-1">Balancen <a class="header-anchor" href="#balancen" aria-label="Permalink to &quot;Balancen&quot;">​</a></h3><p>Brug resultatmål til motivation og retning. Brug procesmål til daglig fokus og udførelse.</p><h2 id="malsætning-for-forskellige-faser" tabindex="-1">Målsætning for forskellige faser <a class="header-anchor" href="#malsætning-for-forskellige-faser" aria-label="Permalink to &quot;Målsætning for forskellige faser&quot;">​</a></h2><h3 id="lavsæson" tabindex="-1">Lavsæson <a class="header-anchor" href="#lavsæson" aria-label="Permalink to &quot;Lavsæson&quot;">​</a></h3><p>Fokus på udviklingsmål:</p><ul><li>Tekniske forbedringer</li><li>Fysisk konditionering</li><li>Opbygning af mentale færdigheder</li><li>Udvid din palet af tæpper</li></ul><h3 id="forsæson" tabindex="-1">Forsæson <a class="header-anchor" href="#forsæson" aria-label="Permalink to &quot;Forsæson&quot;">​</a></h3><p>Overgang til integration:</p><ul><li>Kombination af færdigheder i kamplignende forhold</li><li>Test af forbedringer i venskabelig konkurrence</li><li>Forfining af strategier</li></ul><h3 id="konkurrencesæson" tabindex="-1">Konkurrencesæson <a class="header-anchor" href="#konkurrencesæson" aria-label="Permalink to &quot;Konkurrencesæson&quot;">​</a></h3><p>Skift til ydeevne og proces:</p><ul><li>At udføre det, du har udviklet</li><li>Procesmål for hver kamp</li><li>Minimale tekniske ændringer</li></ul><h3 id="efter-konkurrencen" tabindex="-1">Efter konkurrencen <a class="header-anchor" href="#efter-konkurrencen" aria-label="Permalink to &quot;Efter konkurrencen&quot;">​</a></h3><p>Refleksion og planlægning:</p><ul><li>Analyser hvad der virkede</li><li>Identificer områder for vækst</li><li>Sæt mål for næste cyklus</li></ul><h2 id="almindelige-fejl-ved-malsætning" tabindex="-1">Almindelige fejl ved målsætning <a class="header-anchor" href="#almindelige-fejl-ved-malsætning" aria-label="Permalink to &quot;Almindelige fejl ved målsætning&quot;">​</a></h2><h3 id="for-mange-mal" tabindex="-1">For mange mål <a class="header-anchor" href="#for-mange-mal" aria-label="Permalink to &quot;For mange mål&quot;">​</a></h3><p>Fokus er magt. 2-3 nøglemål slår 10 spredte mål.</p><h3 id="kun-resultatmal" tabindex="-1">Kun resultatmål <a class="header-anchor" href="#kun-resultatmal" aria-label="Permalink to &quot;Kun resultatmål&quot;">​</a></h3><p>Uden procesmål har du ingen køreplan.</p><h3 id="ingen-fleksibilitet" tabindex="-1">Ingen fleksibilitet <a class="header-anchor" href="#ingen-fleksibilitet" aria-label="Permalink to &quot;Ingen fleksibilitet&quot;">​</a></h3><p>Mål bør tilpasses ny information. Ubøjelig overholdelse af forældede mål er spild af indsats.</p><h3 id="sammenligningsbaserede-mal" tabindex="-1">Sammenligningsbaserede mål <a class="header-anchor" href="#sammenligningsbaserede-mal" aria-label="Permalink to &quot;Sammenligningsbaserede mål&quot;">​</a></h3><p>&quot;Vær bedre end [spiller]&quot; lægger din succes i andres hænder.</p><h3 id="at-forsømme-mentale-mal" tabindex="-1">At forsømme mentale mål <a class="header-anchor" href="#at-forsømme-mentale-mal" aria-label="Permalink to &quot;At forsømme mentale mål&quot;">​</a></h3><p>Tekniske og fysiske mål dominerer, men mentale færdigheder afgør ofte, hvem der vinder.</p><h2 id="implementeringsstrategier" tabindex="-1">Implementeringsstrategier <a class="header-anchor" href="#implementeringsstrategier" aria-label="Permalink to &quot;Implementeringsstrategier&quot;">​</a></h2><h3 id="skriv-dem-ned" tabindex="-1">Skriv dem ned <a class="header-anchor" href="#skriv-dem-ned" aria-label="Permalink to &quot;Skriv dem ned&quot;">​</a></h3><p>Der er betydelig større sandsynlighed for, at skriftlige mål bliver nået.</p><h3 id="gennemga-regelmæssigt" tabindex="-1">Gennemgå regelmæssigt <a class="header-anchor" href="#gennemga-regelmæssigt" aria-label="Permalink to &quot;Gennemgå regelmæssigt&quot;">​</a></h3><p>Ugentlig gennemgang holder målene ved lige og giver mulighed for justeringer.</p><h3 id="del-selektivt" tabindex="-1">Del selektivt <a class="header-anchor" href="#del-selektivt" aria-label="Permalink to &quot;Del selektivt&quot;">​</a></h3><p>Del med dem, der vil støtte, ikke underminere.</p><h3 id="visualiser-præstation" tabindex="-1">Visualiser præstation <a class="header-anchor" href="#visualiser-præstation" aria-label="Permalink to &quot;Visualiser præstation&quot;">​</a></h3><p>Forestil dig regelmæssigt at nå dine mål – følelsen, øjeblikket.</p><h3 id="spor-fremskridt" tabindex="-1">Spor fremskridt <a class="header-anchor" href="#spor-fremskridt" aria-label="Permalink to &quot;Spor fremskridt&quot;">​</a></h3><p>Det, der måles, bliver styrt. Hold styr på det.</p><h2 id="nar-malene-ikke-nas" tabindex="-1">Når målene ikke nås <a class="header-anchor" href="#nar-malene-ikke-nas" aria-label="Permalink to &quot;Når målene ikke nås&quot;">​</a></h2><p>Uopfyldte mål er ikke fiaskoer – de er data:</p><ol><li><strong>Analysér</strong>: Hvorfor blev det ikke opnået?</li><li><strong>Lær</strong>: Hvad lærer dette dig?</li><li><strong>Juster</strong>: Rediger målet eller tilgangen</li><li><strong>Fortsæt</strong>: Vedholdenhed slår perfektion</li></ol><h2 id="det-mentale-spil-om-mal" tabindex="-1">Det mentale spil om mål <a class="header-anchor" href="#det-mentale-spil-om-mal" aria-label="Permalink to &quot;Det mentale spil om mål&quot;">​</a></h2><p>Mål påvirker psykologien:</p><ul><li><strong>For let</strong>: Kedsomhed, selvtilfredshed</li><li><strong>For svært</strong>: Angst, modløshed</li><li><strong>Lige tilpas</strong>: Engagement, flow, vækst</li></ul><p>Find det optimale punkt, hvor målene udfordrer uden at blive overvældende.</p><hr><p>| <em>Relateret: <a href="/da/uddannelse/mål/">Introduktion til målsætning</a> | <a href="/da/uddannelse/mål/smarte-mål">SMART Mål</a> | <a href="/da/uddannelse/mål/planlægning">Planlægning af din udvikling</a></em> |</p>',88)])])}]]);export{i as __pageData,t as default};
